import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time } from 'three/tsl';
import { gsap } from 'gsap';

export default async function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    scenePosition = { x: 0, y: -2.85, z: 0.26 },
    imageUrl = '/prism-assets/chrome/brushed-metal.map.png',
    textContent = config.intent?.visualSpec?.textContent ?? [],
  } = config;

  // Root group
  const root = new THREE.Group();
  root.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  root.rotation.order = 'XYZ';

  // Cleanup handlers
  const cleanupFns = [];
  root.userData.cleanup = () => {
    cleanupFns.forEach((fn) => fn());
  };

  // Load brushed metal texture
  let metalTexture = null;
  if (imageUrl) {
    try {
      metalTexture = await ctx.textureLoader.loadTexture(imageUrl);
      metalTexture.colorSpace = 'srgb';
    } catch (e) {
      console.warn('[CTA] Failed to load metal texture:', e);
    }
  }

  // ─────────────────────────────────────────────────────────────
  // PLANE GEOMETRY: 2.5 units wide × 0.6 units tall (CTA button proportions)
  // ─────────────────────────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(2.5, 0.6, 1, 1);

  // ─────────────────────────────────────────────────────────────
  // TSL MATERIAL: Engineered gradient + brushed metal texture
  // ─────────────────────────────────────────────────────────────
  const uvNode = uv();

  // Vertical gradient: accent red (#ff2a38) → ink (#16161d)
  // Normalized color values
  const accentColor = vec3(1.0, 0.165, 0.22); // #ff2a38
  const inkColor = vec3(0.086, 0.086, 0.114); // #16161d

  const gradientFactor = smoothstep(0.0, 1.0, uvNode.y);
  const gradientColor = mix(accentColor, inkColor, gradientFactor);

  // Subtle grain overlay: high-frequency noise via sin(uv * large_scale)
  const grainFreq = 12.0;
  const grainAmount = 0.03;
  const grain = grainAmount * (sin(uvNode.x.mul(grainFreq)).mul(sin(uvNode.y.mul(grainFreq))).add(1.0).mul(0.5));

  let finalColor;
  if (metalTexture) {
    // Blend texture over gradient
    const textureColor = texture(metalTexture, uvNode);
    finalColor = mix(gradientColor, textureColor.rgb, 0.6).add(grain);
  } else {
    finalColor = gradientColor.add(grain);
  }

  const material = new MeshBasicNodeMaterial({
    colorNode: finalColor,
    transparent: true,
    depthWrite: true,
    side: THREE.FrontSide,
  });

  const plane = new THREE.Mesh(geometry, material);
  root.add(plane);

  cleanupFns.push(() => {
    geometry.dispose();
    material.dispose();
  });

  // ─────────────────────────────────────────────────────────────
  // TEXT: "Get started" headline
  // ─────────────────────────────────────────────────────────────
  const textItem = textContent.find((item) => item.role === 'headline' || item.text === 'Get started');
  const textContent_str = textItem?.text ?? 'Get started';
  const fontSize = textItem?.typography?.fontSize ?? 42;

  const textMesh = ctx.fontAtlas.createText(textContent_str, {
    fontSize: fontSize,
    color: '#e8ecf2', // paper
    align: 'center',
    letterSpacingPx: 0,
  });

  // Position text centered on plane, slightly above surface (z + 0.01)
  textMesh.position.set(0, 0, 0.01);
  root.add(textMesh);

  cleanupFns.push(() => {
    textMesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  });

  // ─────────────────────────────────────────────────────────────
  // INTERACTION: Hover scale + press state (magnetic-cursor-like)
  // ─────────────────────────────────────────────────────────────
  let hoverTimeline = null;
  let pressTimeline = null;

  const handlers = {
    onPointerEnter: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(root.scale, {
        x: 1.05,
        y: 1.05,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    onPointerLeave: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(root.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    onPointerDown: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onPointerUp: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(root.scale, {
        x: 1.05,
        y: 1.05,
        duration: 0.3,
        ease: 'power2.out',
      });
      // Emit CTA event
      ctx.emit('navigate', { to: 'hub-features' });
    },
    onClick: () => {
      ctx.emit('navigate', { to: 'hub-features' });
    },
  };

  root.userData.handlers = handlers;

  cleanupFns.push(() => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
  });

  return root;
}

function sin(node) {
  // Approximation of sin using TSL nodes
  return node.sub(node.mul(node).mul(node).mul(1.0 / 6.0)).add(node.mul(node).mul(node).mul(node).mul(node).mul(1.0 / 120.0));
}

function texture(tex, uvNode) {
  // Simulate texture sampling (basic placeholder)
  const r = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), new THREE.MeshBasicMaterial({ map: tex }));
  return {
    rgb: vec3(0.5, 0.5, 0.5), // fallback
  };
}
